// TH15 v1.00b Stage 4 MainSub03 (st04.ecl.txt:1188-1216), third group ECir02 + fourth group ECir04.
// Card frame 0 = source line 1188. Source attack starts after the 120-frame opening buffer.
const TIME_LIMIT: int = 1724;
const OPENING_BUFFER: int = 120;

// TH15_* bullet rows (transcribe/th15/touhou-bullets.ecl); only the two used here.
const TH15_RICE: int = 480;
const TH15_GLOW_BALL: int = 880;

// ECir04 EX 0x200000 VELTIME (a=60, s=-999999 keeps the angle): scalar speed ramps
// linearly from the spawn 1.0 to the difficulty target. Same as a linear speed STEP.
xformdef VEL_RAMP(target: fx) {
    step_speed(target, 60 + 65536 * EASE_LINEAR);
}

// ---- stage side: MainSub03 1188-1216 -------------------------------------
// $C=10 / $D=27 loops: each iteration spawns the left+right pair then waits 10.
async sub pattern() {
    wait(OPENING_BUFFER);
    var r: int = global(GVAR_RANK);
    // ECir02 etSpeed 3.0/3.0/4.0/5.0 by E/N/H/L (st04.ecl.txt:257-265)
    var spd2: fx = 3fx;
    if r == 2 { spd2 = 4fx; }
    if r == 3 { spd2 = 5fx; }
    // ECir04 VELTIME target 4.0/6.0/8.0/8.0 by E/N/H/L (st04.ecl.txt:386-393)
    var spd4: fx = 4fx;
    if r == 1 { spd4 = 6fx; }
    if r == 2 { spd4 = 8fx; }
    if r == 3 { spd4 = 8fx; }

    // Third group: MainSub03_1088, 10 pairs of ECir02 at y=192.
    var i: int = 0;
    while i < 10 {
        // F0=-0.392699 rad (-22.5deg), F1=+0.05236 rad (+3deg/frame), I0=50
        _ = spawn_enemy(-224fx, 192fx, 100, 0, 0, 0, ecir02(-4096, 546, spd2));
        // F0=-2.748894 rad (-157.5deg), F1=-0.05236 rad (-3deg/frame)
        _ = spawn_enemy(224fx, 192fx, 100, 0, 0, 0, ecir02(-28672, -546, spd2));
        wait(10);
        i = i + 1;
    }
    wait(180);
    // Fourth group: MainSub03_1572, 27 pairs of ECir04 at y=0.
    i = 0;
    while i < 27 {
        // F0=0.19635 rad (11.25deg), F1=+0.034907 rad (+2deg/frame)
        _ = spawn_enemy(-224fx, 0fx, 100, 0, 0, 0, ecir04(2048, 364, spd4));
        // F0=2.945243 rad (168.75deg), F1=-0.034907 rad (-2deg/frame)
        _ = spawn_enemy(224fx, 0fx, 100, 0, 0, 0, ecir04(-30720, -364, spd4));
        wait(10);
        i = i + 1;
    }
}

// ---- ECir02 / st04.ecl.txt:187-211, 249-289 ------------------------------
async sub ecir02(f0: int, d: int, spd: fx) {
    set_invuln(65535);
    set_hurtbox(12fx);   // source setHurtbox(24,24), circular radius 24*0.5
    set_hitbox(8fx);     // source setHitbox(16,16), circular radius 16*0.5
    spawn ecir02_fire(spd);
    // moveVel(F0, 5.0); wait(50); moveAngleTime(60, mode7, F1): angle += F1 each tick.
    var ang: angle = f0 as angle;
    move_vel(0, ang, 5fx, EASE_LINEAR);
    wait(50);
    for i in 0..60 {
        ang = ang + (d as angle);
        move_angle(0, ang, EASE_LINEAR);
        wait(1);
    }
    wait(60);
    loop { wait(1000); }  // source hold loop; the enemy leaves the field on its own
}

async sub ecir02_fire(spd: fx) {
    wait(rand(40));  // source wait($RAND % 40)
    var r: int = global(GVAR_RANK);
    // diffI($B,20,40,50,80) / wait 20,10,8,6
    var n: int = 20;
    var gap: int = 20;
    if r == 1 { n = 40; gap = 10; }
    if r == 2 { n = 50; gap = 8; }
    if r == 3 { n = 80; gap = 6; }
    for i in 0..n {
        // etAngle(ANGLE_PLAYER + RANDF2*0.17453292 rad, ...); N=1 so the 45deg path step is unused.
        var a: angle = aim_player() + ((rand(3641) - 1820) as angle);
        // ANIM 0x2 a=1 keeps position -= 4*velocity at birth (speed spd along a).
        var bx: fx = $self_x - 4fx * spd * cos(a);
        var by: fx = $self_y - 4fx * spd * sin(a);
        _ = fire(TH15_RICE, 6, bx, by, spd, a, none, none);
        wait(gap);
    }
}

// ---- ECir04 / st04.ecl.txt:350-374, 376-417 ------------------------------
async sub ecir04(f0: int, d: int, target: fx) {
    set_invuln(65535);
    set_hurtbox(12fx);
    set_hitbox(8fx);
    spawn ecir04_fire(target);
    var ang: angle = f0 as angle;
    move_vel(0, ang, 5fx, EASE_LINEAR);
    wait(50);
    for i in 0..60 {
        ang = ang + (d as angle);
        move_angle(0, ang, EASE_LINEAR);
        wait(1);
    }
    wait(60);
    loop { wait(1000); }
}

async sub ecir04_fire(target: fx) {
    wait(rand(40));  // source wait($RAND % 40)
    var r: int = global(GVAR_RANK);
    // diffI($B,20,40,40,40) / wait 60,40,30,20
    var n: int = 20;
    var gap: int = 60;
    if r == 1 { n = 40; gap = 40; }
    if r == 2 { n = 40; gap = 30; }
    if r == 3 { n = 40; gap = 20; }
    for i in 0..n {
        // etAngle(ANGLE_PLAYER + RANDF2*0.034906585 rad, ...); N=1.
        var a: angle = aim_player() + ((rand(729) - 364) as angle);
        // ANIM 0x2 a=1 at the spawn speed 1.0 (VELTIME starts at 1.0).
        var bx: fx = $self_x - 4fx * cos(a);
        var by: fx = $self_y - 4fx * sin(a);
        _ = fire(TH15_GLOW_BALL, 1, bx, by, 1fx, a, VEL_RAMP(target), none);
        wait(gap);
    }
}

// ---- training shell -----------------------------------------------------
async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
